import { Column, Entity, PrimaryColumn, ManyToOne, JoinColumn } from 'typeorm';
import { JigMaster } from './jig_master.entity';

@Entity({ name: 'JIG_CHECKPOINT' })
export class JigCheckpoint {
    @PrimaryColumn({ length: 20 })
    JIG_NO: string;

    @PrimaryColumn({ type: 'decimal', precision: 3, scale: 0 })
    CHECK_SEQ: number;

    @Column({ length: 200, nullable: false })
    CHECK_POINT: string;

    @Column({ length: 100, nullable: true })
    INSPECTION_TOOL: string | null;

    @Column({ type: 'decimal', precision: 12, scale: 4, nullable: true })
    MIN: number | null;

    @Column({ type: 'decimal', precision: 12, scale: 4, nullable: true })
    MAX: number | null;

    @Column({ length: 20, nullable: true })
    UNIT: string | null;

    @Column({ type: 'decimal', precision: 12, scale: 4, nullable: true })
    MEASURED_VALUE: number | null;

    @ManyToOne(() => JigMaster)
    @JoinColumn({ name: 'JIG_NO', referencedColumnName: 'JIG_NO' })
    jig: JigMaster;
}

import { Column, Entity, PrimaryColumn, ManyToOne, JoinColumn } from 'typeorm';
import { JigMaster } from './jig_master.entity';

@Entity({ name: 'JIG_DEFECT_NG' })
export class JigDefectNg {
    @PrimaryColumn({ length: 20 })
    JIG_NO: string;
    
    @Column({ type: 'varchar2', length: 500, nullable: false })
    DEFECT_DETAIL: string;

    @Column({ type: 'varchar2', length: 100, nullable: false })
    ACTION: string;

    @Column({ type: 'varchar2', length: 100, nullable: false })
    CORRECTIVE: string;

    @Column({ type: 'date', nullable: false })
    PLAN_DATE: Date;

    @Column({ length: 200, nullable: true })
    LOCATION: string | null;

    @ManyToOne(() => JigMaster)
    @JoinColumn({ name: 'JIG_NO', referencedColumnName: 'JIG_NO' })
    jig: JigMaster;
}

import { Column, Entity, PrimaryColumn } from 'typeorm';

@Entity({ name: 'JIG_FORM' })
export class JigForm {
    @PrimaryColumn({ type: 'decimal', precision: 3, scale: 0 })
    NFRMNO: number;

    @PrimaryColumn({ length: 6 })
    VORGNO: string;

    @PrimaryColumn({ type: 'char', length: 2 })
    CYEAR: string;

    @PrimaryColumn({ type: 'char', length: 4 })
    CYEAR2: string;

    @PrimaryColumn({ type: 'decimal', precision: 6, scale: 0 })
    NRUNNO: number;

    @Column({ type: 'varchar2', length: 20, nullable: false })
    FORM_TYPE: 'CREATE' | 'INSPECTION';

    @Column({ type: 'varchar2', length: 20, nullable: false })
    JIG_NO: string;

    @Column({ type: 'varchar2', length: 200, nullable: false })
    JIG_NAME: string;

    @Column({ type: 'varchar2', length: 100, nullable: true })
    DWG: string | null;

    @Column({ type: 'varchar2', length: 2, nullable: true })
    REV: string | null;

    @Column({ type: 'number', precision: 5, scale: 0, nullable: true })
    JIG_QTY: number | null;

    @Column({ type: 'number', precision: 12, scale: 2, nullable: true })
    PRICE: number | null;

    @Column({ type: 'varchar2', length: 100, nullable: true })
    MAKER: string | null;

    @Column({ type: 'date', nullable: true })
    START_USE_DATE: Date | null;

    @Column({ type: 'varchar2', length: 4, nullable: true })
    ITEMNO: string | null;

    @Column({ type: 'varchar2', length: 200, nullable: true })
    JIG_DESC: string | null;

    @Column({ type: 'varchar2', length: 50, nullable: true })
    PROCESS_CODE: string | null;

    @Column({ type: 'varchar2', length: 100, nullable: true })
    LOCATION: string | null;

    @Column({ type: 'varchar2', length: 5, nullable: true })
    PIC_EMPNO: string | null;

    @Column({ type: 'number', precision: 3, scale: 0, nullable: false })
    INSPEC_PERIOD: number;

    @Column({ type: 'varchar2', length: 1000, nullable: true })
    REMARK: string | null;
}

import { Column, Entity, PrimaryColumn, ManyToOne, JoinColumn } from 'typeorm';
import { JigForm } from './jig_form.entity';

@Entity({ name: 'JIG_FORM_DETAIL' })
export class JigFormDetail {
    @PrimaryColumn({ type: 'decimal', precision: 3, scale: 0 })
    NFRMNO: number;

    @PrimaryColumn({ length: 6 })
    VORGNO: string;

    @PrimaryColumn({ type: 'char', length: 2 })
    CYEAR: string;

    @PrimaryColumn({ type: 'char', length: 4 })
    CYEAR2: string;

    @PrimaryColumn({ type: 'decimal', precision: 6, scale: 0 })
    NRUNNO: number;

    @PrimaryColumn({ type: 'decimal', precision: 3, scale: 0 })
    CHECK_SEQ: number;

    @Column({ length: 200, nullable: false })
    CHECK_POINT: string;

    @Column({ length: 100, nullable: true })
    INSPECTION_TOOL: string | null;

    @Column({ type: 'decimal', precision: 12, scale: 4, nullable: true })
    MIN: number | null;

    @Column({ type: 'decimal', precision: 12, scale: 4, nullable: true })
    MAX: number | null;

    @Column({ type: 'decimal', precision: 12, scale: 4, nullable: true })
    MEASURED_VALUE: number | null;

    @Column({ length: 20, nullable: true })
    UNIT: string | null;

    @Column({ length: 10, nullable: true })
    RESULT: string | null;

    @ManyToOne(() => JigForm, { createForeignKeyConstraints: false })
    @JoinColumn([
        { name: 'NFRMNO', referencedColumnName: 'NFRMNO' },
        { name: 'VORGNO', referencedColumnName: 'VORGNO' },
        { name: 'CYEAR', referencedColumnName: 'CYEAR' },
        { name: 'CYEAR2', referencedColumnName: 'CYEAR2' },
        { name: 'NRUNNO', referencedColumnName: 'NRUNNO' },
    ])
    form: JigForm;
}

import { Column, Entity, PrimaryColumn, ManyToOne, JoinColumn } from 'typeorm';
import { JigForm } from './jig_form.entity';

@Entity({ name: 'JIG_FORM_FILE' })
export class JigFormFile {
    @PrimaryColumn({ type: 'decimal', precision: 3, scale: 0 })
    NFRMNO: number;

    @PrimaryColumn({ length: 6 })
    VORGNO: string;

    @PrimaryColumn({ type: 'char', length: 2 })
    CYEAR: string;

    @PrimaryColumn({ type: 'char', length: 4 })
    CYEAR2: string;

    @PrimaryColumn({ type: 'decimal', precision: 6, scale: 0 })
    NRUNNO: number;

    @PrimaryColumn({ type: 'decimal', precision: 6, scale: 0 })
    FILE_SEQ: number;

    @Column({ length: 255, nullable: false })
    FILE_NAME: string;

    @Column({ length: 1000, nullable: false })
    FILE_PATH: string;

    @Column({ length: 100, nullable: true })
    FILE_TYPE: string | null;

    @Column({ type: 'decimal', precision: 12, scale: 0, nullable: true })
    FILE_SIZE: number | null;

    @Column({ length: 10, nullable: true })
    CREATE_BY: string | null;

    @Column({ type: 'date', nullable: false, default: () => 'SYSDATE' })
    CREATE_DATE: Date;

    @ManyToOne(() => JigForm)
    @JoinColumn([
        { name: 'NFRMNO', referencedColumnName: 'NFRMNO' },
        { name: 'VORGNO', referencedColumnName: 'VORGNO' },
        { name: 'CYEAR', referencedColumnName: 'CYEAR' },
        { name: 'CYEAR2', referencedColumnName: 'CYEAR2' },
        { name: 'NRUNNO', referencedColumnName: 'NRUNNO' },
    ])
    form: JigForm;
}

import { Column, Entity, PrimaryColumn, ManyToOne, JoinColumn } from 'typeorm';
import { JigForm } from './jig_form.entity';

@Entity({ name: 'JIG_FORM_NG' })
export class JigFormNg {
    @PrimaryColumn({ type: 'decimal', precision: 3, scale: 0 })
    NFRMNO: number;

    @PrimaryColumn({ length: 6 })
    VORGNO: string;

    @PrimaryColumn({ type: 'char', length: 2 })
    CYEAR: string;

    @PrimaryColumn({ type: 'char', length: 4 })
    CYEAR2: string;

    @PrimaryColumn({ type: 'decimal', precision: 6, scale: 0 })
