    JIG_STATUS: string | null;

    @Column({ length: 1000, nullable: true })
    REMARK: string | null;

    @Column({ type: 'varchar2', length: 4, nullable: true })
    REF_CYEAR2: string | null;

    @Column({ type: 'number', precision: 6, scale: 0, nullable: true })
    REF_NRUNNO: number | null;
}

import { Type } from 'class-transformer';
import {
    IsDefined,
    IsString,
    IsNotEmpty,
    MaxLength,
    IsInt,
    Min,
    Max,
    IsNumber,
    IsOptional,
    IsArray,
    ArrayMaxSize,
    ArrayUnique,
    ValidateNested,
} from 'class-validator';

export class CheckpointDto {
    @IsDefined()
    @IsInt()
    @Min(1)
    @Max(999)
    CHECK_SEQ: number;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(200)
    CHECK_POINT: string;
    @IsOptional()
    @IsString()
    @MaxLength(100)
    INSPECTION_TOOL?: string;
    @IsOptional()
    @IsNumber({ maxDecimalPlaces: 4 })
    @Min(-99999999.9999)
    @Max(99999999.9999)
    MIN?: number;
    @IsOptional()
    @IsNumber({ maxDecimalPlaces: 4 })
    @Min(-99999999.9999)
    @Max(99999999.9999)
    MAX?: number;
    @IsOptional()
    @IsNumber({ maxDecimalPlaces: 4 })
    @Min(-99999999.9999)
    @Max(99999999.9999)
    MEASURED_VALUE?: number | null;
    @IsOptional()
    @IsString()
    @MaxLength(20)
    UNIT?: string;
}

export class ReplaceCheckpointsDto {
    @IsDefined()
    @IsArray()
    @ArrayUnique((item) => item.CHECK_SEQ)
    @ValidateNested({ each: true })
    @Type(() => CheckpointDto)
    CHECKPOINTS: CheckpointDto[];
    @IsOptional()
    @IsString()
    @MaxLength(10)
    UPDATE_BY?: string;
}

import { IntersectionType, PickType, PartialType } from '@nestjs/mapped-types';
import { CreateJigDto } from './create-jig.dto';
import { CreateJigFormDto } from './jig-form.dto';

export class CreateJigRequestDto extends IntersectionType(
    CreateJigFormDto,
    PartialType(PickType(CreateJigDto, ['JIG_NO'] as const)),
) {}

import { Transform } from 'class-transformer';
import {
    IsDefined,
    IsString,
    IsNotEmpty,
    MaxLength,
    IsInt,
    Min,
    Max,
    IsNumber,
    IsOptional,
    IsDateString,
} from 'class-validator';

export class CreateJigDto {
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(20)
    JIG_NO: string;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(200)
    JIG_NAME: string;
    @IsOptional()
    @IsString()
    @MaxLength(100)
    DWG?: string;
    @Transform(({ value }) => typeof value === 'number' ? String(value) : typeof value === 'string' ? value.trim() : value)
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(2)
    REV?: string;
    @IsOptional()
    @IsInt()
    @Min(0)
    @Max(99999)
    JIG_QTY?: number;
    @IsOptional()
    @IsNumber({ maxDecimalPlaces: 2 })
    @Min(0)
    @Max(9999999999.99)
    PRICE?: number;
    @IsOptional()
    @IsString()
    @MaxLength(100)
    MAKER?: string;
    @IsOptional()
    @IsDateString({ strict: true })
    START_USE_DATE?: string;
    @IsOptional()
    @IsString()
    @MaxLength(4)
    ITEMNO?: string;
    @IsOptional()
    @IsString()
    @MaxLength(200)
    JIG_DESC?: string;
    @IsOptional()
    @IsString()
    @MaxLength(50)
    PROCESS_CODE?: string;
    @IsOptional()
    @IsString()
    @MaxLength(100)
    LOCATION?: string;
    @IsOptional()
    @IsString()
    @MaxLength(5)
    PIC_EMPNO?: string;
    @IsDefined()
    @IsInt()
    @Min(1)
    @Max(999)
    INSPEC_PERIOD: number;
    @IsOptional()
    @IsString()
    @MaxLength(1000)
    REMARK?: string;
}

import { IsOptional, IsString, MaxLength } from 'class-validator';
export class FinishInspectionDto {
    @IsOptional()
    @IsString()
    @MaxLength(10)
    UPDATE_BY?: string;
}

import { Type } from 'class-transformer';
import { IntersectionType, PartialType, OmitType } from '@nestjs/mapped-types';
import { PatchJigSnapshotDto } from './jig-snapshot.dto';
import { CheckpointDto } from './checkpoint.dto';
import {
    IsDefined,
    IsBoolean,
    IsString,
    IsNotEmpty,
    MaxLength,
    IsInt,
    Min,
    Max,
    IsNumber,
    IsOptional,
    IsDateString,
    Matches,
    IsIn,
    IsArray,
    ArrayMaxSize,
    ArrayUnique,
    ValidateNested,
} from 'class-validator';

export class JigFormKeyDto {
    @Type(() => Number)
    @IsDefined()
    @IsInt()
    @Min(1)
    @Max(999)
    NFRMNO: number;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(6)
    VORGNO: string;
    @IsDefined()
    @IsString()
    @Matches(/^\d{2}$/)
    CYEAR: string;
    @IsDefined()
    @IsString()
    @Matches(/^\d{4}$/)
    CYEAR2: string;
    @Type(() => Number)
    @IsDefined()
    @IsInt()
    @Min(1)
    @Max(999999)
    NRUNNO: number;
}

export class JigResultDto {
    @IsDefined()
    @IsInt()
    @Min(1)
    @Max(999)
    CHECK_SEQ: number;
    @IsOptional()
    @IsNumber({ maxDecimalPlaces: 4 })
    @Min(-99999999.9999)
    @Max(99999999.9999)
    MEASURED_VALUE?: number;
    @IsOptional()
    @IsIn(['OK', 'NG'])
    RESULT?: 'OK' | 'NG';
}

export class JigNgDto {
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(500)
    DEFECT_DETAIL: string;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(100)
    ACTION: string;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(100)
    CORRECTIVE: string;
    @IsDefined()
    @IsDateString({ strict: true })
    PLAN_DATE: string;
    @IsOptional()
    @IsString()
    @MaxLength(200)
    LOCATION?: string;
}

export class JigFileDto {
    @IsDefined()
    @IsInt()
    @Min(1)
    @Max(999999)
    FILE_SEQ: number;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(255)
    FILE_NAME: string;
    @IsDefined()
    @IsNotEmpty()
    @IsString()
    @MaxLength(1000)
    FILE_PATH: string;
    @IsOptional()
    @IsString()
    @MaxLength(100)
    FILE_TYPE?: string;
    @IsOptional()
    @IsInt()
    @Min(0)
    @Max(999999999999)
    FILE_SIZE?: number;
    @IsOptional()
    @IsString()
    @MaxLength(10)
    CREATE_BY?: string;
}

export class JigFormFileKeyDto extends JigFormKeyDto {
    @Type(() => Number)
    @IsInt()
    @Min(1)
    @Max(999999)
    FILE_SEQ: number;
}

export class CreateJigDetailDto extends IntersectionType(
    CheckpointDto,
    OmitType(JigResultDto, ['CHECK_SEQ'] as const),
) {}

export class SaveJigDetailDto extends IntersectionType(
    JigResultDto,
    PartialType(OmitType(CheckpointDto, ['CHECK_SEQ'] as const), {
        skipNullProperties: false,
    }),
) {}

export class CreateJigFormDto extends IntersectionType(
    JigFormKeyDto,
    PatchJigSnapshotDto,
) {
    // Workflow approver only; not a JIG_FORM or JIG_FORM_NG column.
    @IsOptional()
    @IsString()
    @IsNotEmpty()
    @MaxLength(10)
    PICCODE?: string;
    @IsDefined()
    @IsIn(['CREATE', 'INSPECTION'])
    FORM_TYPE: 'CREATE' | 'INSPECTION';
    @IsOptional()
    @IsString()
    @MaxLength(10)
    CREATE_BY?: string;
    @IsOptional()
    @IsArray()
    @ArrayUnique((item) => item.CHECK_SEQ)
    @ValidateNested({ each: true })
    @Type(() => CreateJigDetailDto)
    DETAILS?: CreateJigDetailDto[];
    @IsOptional()
    @IsArray()
    @ArrayUnique((item) => item.FILE_SEQ)
    @ValidateNested({ each: true })
    @Type(() => JigFileDto)
    FILES?: JigFileDto[];
    @IsOptional()
    @ValidateNested()
    @Type(() => JigNgDto)
    NG?: JigNgDto | null;
    @IsOptional()
    @IsArray()
    @ArrayUnique((item) => item.CHECK_SEQ)
    @ValidateNested({ each: true })
    @Type(() => CheckpointDto)
    CHECKPOINTS?: CheckpointDto[];
}

export class SaveJigFormDto extends PatchJigSnapshotDto {
    @IsOptional()
    @IsBoolean()
    REPLACE_DETAILS?: boolean;
    @IsOptional()
    @IsBoolean()
    REPLACE_FILES?: boolean;
    @IsOptional()
    @IsString()
    @MaxLength(10)
    UPDATE_BY?: string;
    @IsOptional()
    @IsArray()
    @ArrayUnique((item) => item.CHECK_SEQ)
    @ValidateNested({ each: true })
    @Type(() => SaveJigDetailDto)
    DETAILS?: SaveJigDetailDto[];
    @IsOptional()
    @IsArray()
    @ArrayUnique((item) => item.FILE_SEQ)
    @ValidateNested({ each: true })
    @Type(() => JigFileDto)
    FILES?: JigFileDto[];
    @IsOptional()
    @ValidateNested()
    @Type(() => JigNgDto)
    NG?: JigNgDto | null;
}

import { OmitType, PartialType } from '@nestjs/mapped-types';
import { CreateJigDto } from './create-jig.dto';

// Only fields persisted in the form snapshot; no master lifecycle or audit fields.
export class JigSnapshotDto extends OmitType(CreateJigDto, [
    'JIG_NO',
] as const) {}

export class PatchJigSnapshotDto extends PartialType(JigSnapshotDto, {
    skipNullProperties: false,
}) {}

import { IsDefined, ValidateNested } from 'class-validator';
import { Type } from 'class-transformer';
import { JigFormKeyDto, SaveJigFormDto } from './jig-form.dto';
export class UpdateJigDto extends SaveJigFormDto {
    @IsDefined()
    @ValidateNested()
    @Type(() => JigFormKeyDto)
    FORM_KEY: JigFormKeyDto;
}

