    it.each([0, -1, 1.5, 1000])(
        'rejects invalid inspection period %s',
        async (period) => {
            const dto = plainToInstance(CreateJigDto, {
                JIG_NO: 'A',
                JIG_NAME: 'Jig',
                INSPEC_PERIOD: period,
            });
